    #[test]
    fn add_text_book_builds_reference_trail_ids_and_fingerprint() {
        let (mut engine, _dir) = make_engine();
        let text =
            "<h1>ספר בראשית</h1>\n<h2>פרק א</h2>\nבְּרֵאשִׁית ברא אלהים\n<h2>פרק ב</h2>\nויכלו השמים";
        let added = engine
            .add_text_book(
                "בראשית".to_string(),
                "/root".to_string(),
                "/books/bereshit.txt".to_string(),
                5,
                DEFAULT_GENERATION_ORDER,
                text.to_string(),
                None,
                TextStorage::InIndex,
                None,
            )
            .unwrap();
        assert_eq!(added, 5);
        engine.commit().unwrap();

        let results = engine
            .search_exact(
                "ויכלו".to_string(),
                vec![],
                10,
                0,
                ResultsOrder::Catalogue,
                false,
                false,
                None,
            )
            .unwrap();
        assert_eq!(results.len(), 1);
        let hit = &results[0];
        // הכותרת החדשה של פרק ב החליפה את פרק א ב-trail (אותו prefix "<h2>").
        assert_eq!(hit.reference, "ספר בראשית, פרק ב");
        assert_eq!(hit.segment, 4);
        // id = ((catalogue_order+1) << 32) + ordinal+1, כמו ב-Dart.
        assert_eq!(hit.id, ((5u64 + 1) << 32) + 5);
        assert_eq!(hit.title, "בראשית");
        assert!(!hit.is_pdf);

        // הטקסט המאונדקס מנורמל (הניקוד הוסר) והחיפוש מוצא אותו.
        let nikud_hit = engine
            .search_exact(
                "בראשית ברא".to_string(),
                vec![],
                10,
                0,
                ResultsOrder::Catalogue,
                false,
                false,
                None,
            )
            .unwrap();
        assert_eq!(nikud_hit.len(), 1);

        // טביעת האצבע נחתמה על הספר, זהה לחישוב הציבורי הקנוני
        // (טקסט + metadata).
        let fingerprints = engine.get_book_fingerprints().unwrap();
        assert_eq!(
            fingerprints.get("/books/bereshit.txt"),
            Some(&compute_book_fingerprint(
                text.to_string(),
                "בראשית".to_string(),
                "/root".to_string(),
                5,
                DEFAULT_GENERATION_ORDER,
                None,
            ))
        );
        // שינוי metadata בלבד (סדר דורות) משנה את החתימה — הספר יזוהה
        // כדורש אינדוקס-מחדש.
        assert_ne!(
            compute_book_fingerprint(
                text.to_string(),
                "בראשית".to_string(),
                "/root".to_string(),
                5,
                DEFAULT_GENERATION_ORDER,
                None,
            ),
            compute_book_fingerprint(
                text.to_string(),
                "בראשית".to_string(),
                "/root".to_string(),
                5,
                7,
                None,
            ),
        );
        // סדר ה-extra_facets אינו משנה את החתימה.
        assert_eq!(
            compute_book_fingerprint(
                text.to_string(),
                "בראשית".to_string(),
                "/root".to_string(),
                5,
                DEFAULT_GENERATION_ORDER,
                Some(vec![
                    "/author/רש\"י".to_string(),
                    "/era/ראשונים".to_string()
                ]),
            ),
            compute_book_fingerprint(
                text.to_string(),
                "בראשית".to_string(),
                "/root".to_string(),
                5,
                DEFAULT_GENERATION_ORDER,
                Some(vec![
                    "/era/ראשונים".to_string(),
                    "/author/רש\"י".to_string()
                ]),
            ),
        );

        // חתימת הטקסט-בלבד נחתמה גם היא, זהה לחישוב הציבורי — ובניגוד
        // לקנונית, אינה תלויה בסדר הקטלוגי או בשאר ה-metadata.
        let text_fingerprints = engine.get_book_text_fingerprints().unwrap();
        assert_eq!(
            text_fingerprints.get("/books/bereshit.txt"),
            Some(&compute_content_fingerprint(text.to_string()))
        );
    }

    #[test]
    fn breaking_tag_in_a_line_keeps_the_words_separate() {
        // Otzaria/otzaria#949: `<br>` בתוך שורה (ספרים אישיים מומרים) הדביק
        // את שתי המילים לטוקן אחד — הן הוצגו דבוקות בתוצאות, וחיפוש של כל
        // אחת מהן החטיא.
        let (mut engine, _dir) = make_engine();
        engine
            .add_text_book(
                "חוזק יד".to_string(),
                "/root".to_string(),
                "/books/chozek.txt".to_string(),
                1,
                DEFAULT_GENERATION_ORDER,
                "יותר בכבוד המורים<br>כי אב הביאו לעולם".to_string(),
                None,
                TextStorage::InIndex,
                None,
            )
            .unwrap();
        engine.commit().unwrap();

        for query in ["המורים", "כי", "המורים כי"] {
            let results = engine
                .search_exact(
                    query.to_string(),
                    vec![],
                    10,
                    0,
                    ResultsOrder::Catalogue,
                    false,
                    false,
                    None,
                )
                .unwrap();
            assert_eq!(results.len(), 1, "query {query:?}");
            // הטקסט השמור — שממנו נבנה קטע התוצאה — מופרד ברווח (תגי
            // ההדגשה של המנוע עשויים לעטוף את ההתאמות).
            let plain = results[0]
                .text
                .replace("<font color=red>", "")
                .replace("</font>", "");
            assert!(plain.contains("המורים כי"), "stored text: {plain}");
        }
    }

    #[test]
    fn paired_readings_share_one_position_so_either_completes_the_phrase() {
        // בראשית ח, יז כפי שהוא במסד: קרי וכתיב בזוג `(X) [Y]`.
        let line = "עַל־הָאָ֖רֶץ <span class=\"mam-kq\"><span class=\"mam-kq-k\">(הוצא)</span> \
                    <span class=\"mam-kq-q\">[הַיְצֵ֣א]</span></span> אִתָּ֑ךְ";
        let (mut engine, _dir) = make_engine();
        for (id, text) in [(1, line), (2, "כי [אם] עונותיכם היו מבדילים")] {
            engine
                .add_document(
                    id,
                    "title",
                    "ref",
                    "/root",
                    text,
                    id,
                    false,
                    &format!("/books/{id}.txt"),
                    None,
                    None,
                    None,
                )
                .unwrap();
        }
        engine.commit().unwrap();
        let count = |query: &str, distance: u32| {
            count_advanced_default(
                &engine,
                query.to_string(),
                vec![],
                distance,
                HashMap::new(),
                HashMap::new(),
                HashMap::new(),
                false,
                false,
                SearchScope::WordDistance,
            )
            .unwrap()
        };

        assert_eq!(count("הארץ היצא אתך", 0), 1);
        assert_eq!(count("הארץ הוצא אתך", 0), 1);
        // הזוג הוא מילה אחת: בלי מרווח הוא אינו נבלע.
        assert_eq!(count("הארץ אתך", 0), 0);
        assert_eq!(count("הארץ אתך", 1), 1);
        // זוג שהודבק לשאילתה מצטמצם לקריאה השנייה.
        assert_eq!(count("הארץ (הוצא) [היצא] אתך", 0), 1);
        // מילה בסוגריים מרובעים לבדה אינה זוג, ונשארת מילה נפרדת.
        assert_eq!(count("כי עונותיכם", 0), 0);
        assert_eq!(count("כי אם עונותיכם", 0), 1);
    }

    #[test]
    fn paired_readings_preserve_query_boundaries_and_real_maqaf_readings() {
        let (mut engine, _dir) = make_engine();
        let documents = [
            // Numbers 23:13 and 1 Samuel 20:24: a maqaf is inside the
            // qere brackets, with the following word immediately adjacent.
            (1, "בלק (לך) [לכה־]נא"),
            (2, "המלך (על) [אל־]הלחם"),
            // No whitespace before '(' still means a separate token.
            (3, "אמר(ת) [רבא] משום"),
            (4, "ראשון (א־ב) [ג] סוף"),
            (5, "שני (א) [ב,ג] סוף"),
            (6, "סימן (ח')[ו'] (ט')[י'] שם"),
        ];
        for (id, text) in documents {
            add(&mut engine, id, text, &format!("/books/{id}.txt"));
        }
        engine.commit().unwrap();
        let count = |query: &str, distance: u32| {
            count_advanced_default(
                &engine,
                query.to_string(),
                vec![],
                distance,
                HashMap::new(),
                HashMap::new(),
                HashMap::new(),
                false,
                false,
                SearchScope::WordDistance,
            )
            .unwrap()
        };
        for (query, document_id) in [
            ("בלק לך נא", 1),
            ("בלק לכה נא", 1),
            ("בלק (לך) [לכה־]נא", 1),
            ("המלך על הלחם", 2),
            ("המלך אל הלחם", 2),
            ("אמר רבא משום", 3),
            ("אמר(ת) [רבא] משום", 3),
            ("סימן ח ט שם", 6),
            ("סימן ו י שם", 6),
            ("סימן (ח')[ו'] (ט')[י'] שם", 6),
        ] {
            assert_eq!(count(query, 0), 1, "query {query}");
            let source = documents
                .iter()
                .find(|(id, _)| *id == document_id)
                .unwrap()
                .1;
            let pattern = generate_highlight_pattern(
                query.to_string(),
                0,
                HashMap::new(),
                HashMap::new(),
                HashMap::new(),
            )
            .unwrap();
            assert_eq!(pattern.combined_pattern, "(?!)");
            let matches = pattern
                .matcher
                .unwrap()
                .find_matches(source.to_string(), vec![]);
            assert_eq!(matches.len(), 1, "highlight/index parity: {query}");
            assert_eq!(
                matches[0].word_ranges.len(),
                split_query_words(query.to_string()).len()
            );
        }
        for (query, document_id) in [("ראשון סוף", 4), ("שני סוף", 5)] {
            assert_eq!(count(query, 1), 0, "multi-token reading: {query}");
            assert_eq!(count(query, 3), 1, "full gap: {query}");
            let source = documents
                .iter()
                .find(|(id, _)| *id == document_id)
                .unwrap()
                .1;
            for (distance, expected_matches) in [(1, 0), (3, 1)] {
                let pattern = generate_highlight_pattern(
                    query.to_string(),
                    distance,
                    HashMap::new(),
                    HashMap::new(),
                    HashMap::new(),
                )
                .unwrap();
                assert_eq!(
                    pattern
                        .matcher
                        .unwrap()
                        .find_matches(source.to_string(), vec![])
                        .len(),
                    expected_matches,
                    "punctuation highlight/index parity: {query}, distance={distance}"
                );
            }
        }
        // Neither quote-free twins nor paired readings consume an extra word.
        assert_eq!(count("סימן שם", 1), 0);
        assert_eq!(count("סימן שם", 2), 1);
        assert_eq!(count("סימן ח ו ט שם", 0), 0);
    }

    #[test]
    fn query_word_spans_agree_with_full_query_tokens_and_original_utf16_ranges() {
        for query in [
            "הארץ (הוצא) [היצא] אתך",
            "הארץ(הוצא)\n[היצא] אתך",
            "(אב) [אב] אב",
            "😀 הארץ(הוצא) [היצא] אתך 😀",
            "בלק (לך) [לכה־]נא",
            "(א)[ב](ג)[ד] סוף",
            "רמב''ם-משה תוס׳ רמח”ל",
            "א.ב יב[ע]ר לה\u{FEFF}תיר",
            "שָׁלוֹם מ\u{FB1D}ם \u{FB4F}הים",
            "(א־ב) [ג] (א) [ב,ג]",
            "כי [אם] עונותיכם",
        ] {
            let spans = query_word_spans(query.to_string());
            assert_eq!(
                spans.iter().map(|s| s.word.clone()).collect::<Vec<_>>(),
                split_query_words(query.to_string()),
                "full-query words differ for {query}"
            );
            let utf16 = query.encode_utf16().collect::<Vec<_>>();
            let mut previous_end = 0;
            for span in spans {
                assert!(span.start >= previous_end, "overlapping spans: {query}");
                let source = String::from_utf16(&utf16[span.start as usize..span.end as usize])
                    .expect("source range split a surrogate pair");
                assert_eq!(
                    split_query_words(source),
                    vec![span.word],
                    "source range changed the selected word: {query}"
                );
                previous_end = span.end;
            }
        }
        assert_eq!(
            query_word_spans("(אב) [אב] אב".to_string()),
            vec![
                QueryWordSpan {
                    word: "אב".to_string(),
                    start: 6,
                    end: 8
                },
                QueryWordSpan {
                    word: "אב".to_string(),
                    start: 10,
                    end: 12
                },
            ]
        );
        assert_eq!(
            query_word_spans("😀 רמב''ם-משה".to_string()),
            vec![
                QueryWordSpan {
                    word: "רמב\"ם".to_string(),
                    start: 3,
                    end: 9
                },
                QueryWordSpan {
                    word: "משה".to_string(),
                    start: 10,
                    end: 13
                },
            ]
        );
    }

    #[test]
    fn parallel_term_collection_equals_the_sequential_loop() {
        use std::sync::atomic::{AtomicUsize, Ordering};
        let (mut engine, _dir) = make_engine();
        engine.set_bulk_indexing(true).unwrap();
        let words = [
            "ספר",
            "ספרים",
            "הספר",
            "מספר",
            "סופר",
            "ספרא",
            "בספרו",
            "תורה",
        ];
        for (segment, chunk) in words.chunks(2).enumerate() {
            for (i, word) in chunk.iter().enumerate() {
                let id = (segment * 10 + i) as u64;
                engine
                    .add_document(
                        id,
                        "title",
                        "ref",
                        "/root",
                        &format!("{word} {word} ספר אחר"),
                        id,
                        false,
                        &format!("/books/{id}.txt"),
                        None,
                        None,
                        None,
                    )
                    .unwrap();
            }
            engine.commit().unwrap();
        }
        assert!(engine.get_segment_count().unwrap() > 1);

        let searcher = engine.index_reader.searcher();
        let text = engine.schema.get_field("text").unwrap();
        let inverted: Vec<_> = searcher
            .segment_readers()
            .iter()
            .map(|r| r.inverted_index(text).unwrap())
            .collect();
        let regexes: Vec<tantivy_fst::Regex> = [".{0,3}ספר.{0,3}", "סופר", ".{0,2}ס.{0,3}"]
            .iter()
            .map(|p| tantivy_fst::Regex::new(p).unwrap())
            .collect();

        struct CountedRegex {
            regex: tantivy_fst::Regex,
            starts: Arc<AtomicUsize>,
        }
        impl Automaton for CountedRegex {
            type State = <tantivy_fst::Regex as Automaton>::State;
            fn start(&self) -> Self::State {
                self.starts.fetch_add(1, Ordering::Relaxed);
                self.regex.start()
            }
            fn is_match(&self, state: &Self::State) -> bool {
                self.regex.is_match(state)
            }
            fn can_match(&self, state: &Self::State) -> bool {
                self.regex.can_match(state)
            }
            fn accept(&self, state: &Self::State, byte: u8) -> Self::State {
                self.regex.accept(state, byte)
            }
        }
        let counted: Vec<_> = (0..8)
            .map(|_| CountedRegex {
                regex: tantivy_fst::Regex::new(".*").unwrap(),
                starts: Arc::new(AtomicUsize::new(0)),
            })
            .collect();
        assert!(SearchEngine::collect_automatons_terms(
            &inverted,
            &counted,
            1,
            u64::MAX,
            &mut HashSet::new(),
            &mut 0,
        )
        .unwrap());
        assert!(counted[0].starts.load(Ordering::Relaxed) > 0);
        assert!(counted[1..]
            .iter()
            .all(|automaton| automaton.starts.load(Ordering::Relaxed) == 0));

        // The common first branch can also consume the budget across all
        // segments, rather than on its first hit. Later branches stay idle.
        let first_budget: u64 = inverted
            .iter()
            .map(|reader| {
                let mut stream = reader.terms().search(&counted[0]).into_stream().unwrap();
                let mut cost = 0;
                while stream.advance() {
                    cost += u64::from(stream.value().doc_freq);
                }
                cost
            })
            .sum();
        for automaton in &counted {
            automaton.starts.store(0, Ordering::Relaxed);
        }
        assert!(SearchEngine::collect_automatons_terms(
            &inverted,
            &counted,
            1000,
            first_budget,
            &mut HashSet::new(),
            &mut 0,
        )
        .unwrap());
        assert!(counted[0].starts.load(Ordering::Relaxed) > 0);
        assert!(counted[1..]
            .iter()
            .all(|automaton| automaton.starts.load(Ordering::Relaxed) == 0));

        let pool = rayon::ThreadPoolBuilder::new()
            .num_threads(4)
            .build()
            .unwrap();
        // Narrow leading-wildcard and empty scans can traverse the whole
        // dictionary. Their probe hits must be reused, so each visited
        // segment starts exactly as many scans as the sequential collector.
        for pattern in [".*ספר", "סופר", ".*missing"] {
            let narrow = [CountedRegex {
                regex: tantivy_fst::Regex::new(pattern).unwrap(),
                starts: Arc::new(AtomicUsize::new(0)),
            }];
            for initial in [HashSet::new(), HashSet::from(["ספר".to_owned()])] {
                for max_expansions in [0, 1, 1000] {
                    for budget in [0, 1, u64::MAX] {
                        narrow[0].starts.store(0, Ordering::Relaxed);
                        let mut actual = initial.clone();
                        let mut actual_cost = 0;
                        let actual_truncated = pool
                            .install(|| {
                                SearchEngine::collect_automatons_terms(
                                    &inverted,
                                    &narrow,
                                    max_expansions,
                                    budget,
                                    &mut actual,
                                    &mut actual_cost,
                                )
                            })
                            .unwrap();
                        let actual_scans = narrow[0].starts.swap(0, Ordering::Relaxed);
                        let mut seq = initial.clone();
                        let mut seq_cost = 0;
                        let mut seq_truncated = false;
                        for reader in &inverted {
                            if SearchEngine::collect_automaton_terms(
                                reader,
                                &narrow[0],
                                max_expansions,
                                budget,
                                &mut seq,
                                &mut seq_cost,
                            )
                            .unwrap()
                            {
                                seq_truncated = true;
                                break;
                            }
                        }
                        assert_eq!(actual, seq, "pattern={pattern}");
                        assert_eq!(actual_cost, seq_cost, "pattern={pattern}");
                        assert_eq!(actual_truncated, seq_truncated, "pattern={pattern}");
                        assert_eq!(
                            actual_scans,
                            narrow[0].starts.load(Ordering::Relaxed),
                            "narrow probe repeated a scan: pattern={pattern}",
                        );
                    }
                }
            }
        }
        // Existing terms, per-segment duplicates, exhausted initial budgets,
        // and shrinking waves all retain the original sequential prefix.
        for initial in [vec![], vec!["ספר"], vec!["ספר", "סופר", "not-in-index"]] {
            for max_expansions in [0, 1, 2, 3, 7, 1000] {
                for budget in [0, 1, 3, 5, 9, u64::MAX] {
                    for initial_cost in [0, 2, budget] {
                        // Avoid an irrelevant arithmetic overflow in both
                        // collectors when starting already at u64::MAX.
                        if initial_cost == u64::MAX {
                            continue;
                        }
                        let initial: HashSet<String> =
                            initial.iter().map(|term| (*term).to_owned()).collect();
                        let mut seq = initial.clone();
                        let mut seq_cost = initial_cost;
                        let mut seq_truncated = false;
                        'outer: for regex in &regexes {
                            for inv in &inverted {
                                if SearchEngine::collect_automaton_terms(
                                    inv,
                                    regex,
                                    max_expansions,
                                    budget,
                                    &mut seq,
                                    &mut seq_cost,
                                )
                                .unwrap()
                                {
                                    seq_truncated = true;
                                    break 'outer;
                                }
                            }
                        }
                        let mut par = initial;
                        let mut par_cost = initial_cost;
                        let par_truncated = pool
                            .install(|| {
                                SearchEngine::collect_automatons_terms(
                                    &inverted,
                                    &regexes,
                                    max_expansions,
                                    budget,
                                    &mut par,
                                    &mut par_cost,
                                )
                            })
                            .unwrap();
                        let case = format!("max_expansions={max_expansions} budget={budget} initial_cost={initial_cost}");
                        assert_eq!(par, seq, "{case}");
                        assert_eq!(par_cost, seq_cost, "{case}");
                        assert_eq!(par_truncated, seq_truncated, "{case}");
                    }
                }
            }
        }
    }

    #[test]
    fn broad_term_collection_on_few_segments_retains_sequential_prefix() {
        let (mut engine, _dir) = make_engine();
        engine.set_bulk_indexing(true).unwrap();
        let letters: Vec<char> = "אבגדהוזחטיכלמנסעפצקרשת".chars().collect();
        let term = |index: usize| {
            format!(
                "מלה{}{}",
                letters[index / letters.len()],
                letters[index % letters.len()]
            )
        };
        for segment in 0..3 {
            let words: Vec<_> = (segment * 16..segment * 16 + 32).map(term).collect();
            add(
                &mut engine,
                segment as u64,
                &words.join(" "),
                &format!("/books/{segment}.txt"),
            );
            engine.commit().unwrap();
        }
        let searcher = engine.index_reader.searcher();
        let text = engine.schema.get_field("text").unwrap();
        let inverted: Vec<_> = searcher
            .segment_readers()
            .iter()
            .map(|reader| reader.inverted_index(text).unwrap())
            .collect();
        assert_eq!(inverted.len(), 3);
        let regexes = [tantivy_fst::Regex::new("מלה.*").unwrap()];

        // Wide dictionaries exercise the probe and parallel waves, while
        // budgets reached inside the probe select synchronous collection.
        // Overlapping dictionaries and prefilled sets retain the same prefix,
        // including budgets reached immediately after the ninth probe hit.
        for threads in [1, 4] {
            let pool = rayon::ThreadPoolBuilder::new()
                .num_threads(threads)
                .build()
                .unwrap();
            for segment_count in [2, 3] {
                let readers = &inverted[..segment_count];
                for initial in [HashSet::new(), (0..20).map(term).collect()] {
                    for max_expansions in [0, 1, 8, 9, 10, 24, 40, 1000] {
                        for budget in [0, 1, 8, 9, 10, 11, 24, 40, 64, 1000] {
                            let mut seq = initial.clone();
                            let mut seq_cost = 2;
                            let mut seq_truncated = false;
                            for reader in readers {
                                if SearchEngine::collect_automaton_terms(
                                    reader,
                                    &regexes[0],
                                    max_expansions,
                                    budget,
                                    &mut seq,
                                    &mut seq_cost,
                                )
                                .unwrap()
                                {
                                    seq_truncated = true;
                                    break;
                                }
                            }
                            let mut actual = initial.clone();
                            let mut actual_cost = 2;
                            let actual_truncated = pool
                                .install(|| {
                                    SearchEngine::collect_automatons_terms(
                                        readers,
                                        &regexes,
                                        max_expansions,
                                        budget,
                                        &mut actual,
                                        &mut actual_cost,
                                    )
                                })
                                .unwrap();
                            let case = format!("threads={threads} segments={segment_count} cap={max_expansions} budget={budget}");
                            assert_eq!(actual, seq, "{case}");
                            assert_eq!(actual_cost, seq_cost, "{case}");
                            assert_eq!(actual_truncated, seq_truncated, "{case}");
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn term_budget_respects_segment_order_before_dictionary_order() {
        let (mut engine, _dir) = make_engine();
        engine.set_bulk_indexing(true).unwrap();
        add(
            &mut engine,
            1,
            "מלהד מלהה מלהו מלהז מלהח מלהט",
            "/books/later.txt",
        );
        engine.commit().unwrap();
        add(&mut engine, 2, "מלהא", "/books/early.txt");
        engine.commit().unwrap();
        let searcher = engine.index_reader.searcher();
        let text = engine.schema.get_field("text").unwrap();
        let early = Term::from_field_text(text, "מלהא");
        let mut inverted: Vec<_> = searcher
            .segment_readers()
            .iter()
            .map(|reader| reader.inverted_index(text).unwrap())
            .collect();
        assert_eq!(inverted.len(), 2);
        // Reproduce the layout that made the overflow phrase test flaky:
        // a segment containing later terms exhausts the cap before the
        // segment that contains the globally earliest term is visited.
        inverted.sort_by_key(|reader| reader.get_term_info(&early).unwrap().is_some());
        let regexes = vec![tantivy_fst::Regex::new("מלה.*").unwrap()];
        let mut seq = HashSet::new();
        let mut seq_cost = 0;
        assert!(SearchEngine::collect_automaton_terms(
            &inverted[0],
            &regexes[0],
            5,
            u64::MAX,
            &mut seq,
            &mut seq_cost,
        )
        .unwrap());
        assert!(!seq.contains("מלהא"));
        let mut parallel = HashSet::new();
        let mut parallel_cost = 0;
        assert!(SearchEngine::collect_automatons_terms(
            &inverted,
            &regexes,
            5,
            u64::MAX,
            &mut parallel,
            &mut parallel_cost,
        )
        .unwrap());
        assert_eq!(parallel, seq);
        assert_eq!(parallel_cost, seq_cost);
    }

    #[test]
    fn add_document_and_batch_normalize_like_add_text_book() {
        // ה-API הישירים חשופים ב-FFI — ההנחה "הקלט כבר מנורמל" נאכפת:
        // HTML מוסר, ניקוד מוסר מהשדה הרגיל, והעותק המנוקד נבנה מהגולמי.
        let raw = "<b>בְּרֵאשִׁית</b>  בָּרָא אלהים";
        let (mut engine, _dir) = make_engine();
        engine
            .add_document(
                1,
                "title",
                "ref",
                "/root",
                raw,
                0,
                false,
                "/books/a.txt",
                None,
                None,
                None,
            )
            .unwrap();
        engine
            .add_documents_batch(vec![DocumentInput {
                id: 2,
                title: "title".to_string(),
                reference: "ref".to_string(),
                topics: "/root".to_string(),
                text: raw.to_string(),
                segment: 1,
                is_pdf: false,
                file_path: "/books/b.txt".to_string(),
                content_hash: None,
                text_hash: None,
                text_vocalized: Some("<b>בְּרֵאשִׁית</b>  בָּרָא אלהים".to_string()),
                section_id: None,
                generation_order: None,
                extra_facets: None,
                text_storage: None,
            }])
            .unwrap();
        engine
            .upsert_documents_batch(vec![DocumentInput {
                id: 3,
                title: "title".to_string(),
                reference: "ref".to_string(),
                topics: "/root".to_string(),
                text: raw.to_string(),
                segment: 2,
                is_pdf: false,
                file_path: "/books/c.txt".to_string(),
                content_hash: None,
                text_hash: None,
                text_vocalized: Some("<b>בְּרֵאשִׁית</b>  בָּרָא אלהים".to_string()),
                section_id: None,
                generation_order: None,
                extra_facets: None,
                text_storage: None,
            }])
            .unwrap();
        engine.commit().unwrap();

        // שלושת המסלולים מאונדקסים ומאוחסנים בצורה המנורמלת.
        let results = engine
            .search_exact(
                "בראשית ברא".to_string(),
                vec![],
                10,
                0,
                ResultsOrder::Catalogue,
                false,
                false,
                None,
            )
            .unwrap();
        assert_eq!(results.len(), 3);
        for hit in &results {
            // הטקסט השמור מנורמל (בלי ה-HTML המקורי ובלי ניקוד בשדה
            // הרגיל); תגי ה-font הם עיטור ההדגשה של תוצאת החיפוש.
            let clean = hit
                .text
                .replace("<font color=red>", "")
                .replace("</font>", "");
            assert_eq!(clean, "בראשית ברא אלהים");
        }

        // העותקים המנוקדים נורמלו גם הם (ה-HTML הוסר): מסלולי ה-batch
        // (add/upsert) דרך הנרמול הנאכף על text_vocalized שסופק, ומסלול
        // add_document דרך העותק שהוא בונה בעצמו מהקלט הגולמי — חיפוש
        // מנוקד מוצא את כולן.
        let vocalized = engine
            .search_exact(
                "בְּרֵאשִׁית".to_string(),
                vec![],
                10,
                0,
                ResultsOrder::Catalogue,
                true,
                false,
                None,
            )
            .unwrap();
        assert_eq!(vocalized.len(), 3);
    }

    #[test]
    fn analyzers_drop_tokens_longer_than_cap() {
        // RemoveLongFilter על כל האנליזטורים: זבל base64 (נמדדו ריצות של
        // אלפי תווים בקורפוס) לא נכנס למילון הטרמים — וגם צד השאילתה מפיל
        // את הטוקן, כך שספירת PhraseQuery נשארת עקבית עם האינדקס.
        let (mut engine, _dir) = make_engine();
        let garbage = "א".repeat(80); // 160 בייט — מעל התקרה
        let long_but_legit = "א".repeat(60); // 120 בייט — מתחת לתקרה
        add(
            &mut engine,
            1,
            &format!("שלום {garbage} עולם"),
            "/books/junk.txt",
        );
        engine.commit().unwrap();

        // הטוקן הארוך לא נטמע; המילים סביבו כן.
        assert_eq!(
            engine
                .index_token_texts(&format!("שלום {garbage}"))
                .unwrap(),
            vec!["שלום"]
        );
        assert_eq!(engine.index_token_texts(&long_but_legit).unwrap().len(), 1);
        assert_eq!(search_ids(&mut engine, "שלום"), vec![1]);
        assert_eq!(search_ids(&mut engine, &garbage), Vec::<u64>::new());
    }

    #[test]
    fn add_text_book_bytes_matches_string_path() {
        // מסלול הבייטים (SQLite BLOB → Uint8List) חייב לייצר בדיוק את אותם
        // מסמכים ואותה טביעת אצבע כמו מסלול ה-String.
        let text =
            "<h1>ספר בראשית</h1>\n<h2>פרק א</h2>\nבְּרֵאשִׁית ברא אלהים\n<h2>פרק ב</h2>\nויכלו השמים";
        let (mut engine, _dir) = make_engine();
        let added = engine
            .add_text_book_bytes(
                "בראשית".to_string(),
                "/root".to_string(),
                "/books/bereshit.txt".to_string(),
                5,
                DEFAULT_GENERATION_ORDER,
                text.as_bytes().to_vec(),
                None,
                TextStorage::InIndex,
                None,
            )
            .unwrap();
        assert_eq!(added, 5);
        engine.commit().unwrap();

        let results = engine
            .search_exact(
                "ויכלו".to_string(),
                vec![],
                10,
                0,
                ResultsOrder::Catalogue,
                false,
                false,
                None,
            )
            .unwrap();
        assert_eq!(results.len(), 1);
        assert_eq!(results[0].reference, "ספר בראשית, פרק ב");
        assert_eq!(results[0].id, ((5u64 + 1) << 32) + 5);

        let fingerprints = engine.get_book_fingerprints().unwrap();
        assert_eq!(
            fingerprints.get("/books/bereshit.txt"),
            Some(&compute_book_fingerprint(
                text.to_string(),
                "בראשית".to_string(),
                "/root".to_string(),
                5,
                DEFAULT_GENERATION_ORDER,
                None,
            ))
        );
        let text_fingerprints = engine.get_book_text_fingerprints().unwrap();
        assert_eq!(
            text_fingerprints.get("/books/bereshit.txt"),
            Some(&compute_content_fingerprint(text.to_string()))
        );
    }

